package it.penny.api.margins;
import org.springframework.web.bind.annotation.*;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.security.core.Authentication;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
@RestController @RequestMapping("/api/margins")
public class MarginsController {
 private final MarginService s;public MarginsController(MarginService s){this.s=s;}
 public record Profile(String name,List<String> components){}
 public record Rule(Long profileId,Long previousId,String name,String component,String calculation,BigDecimal value,Integer sign,Map<String,Object> conditions,LocalDate validFrom,LocalDate validTo,Integer priority,String status,String reference){}
 public record Change(String kind,BigDecimal amount,String reason){}
 public record RuleChange(LocalDate validTo,String reason,LocalDate effectiveOn){}
 @GetMapping("/profiles") public Map<String,Object> profiles(Authentication a){s.require(a,"MARGINS_READ");var rows=s.database().queryForList("SELECT id,name,components FROM penny_margin_profiles ORDER BY name");for(var r:rows){try{r.put("components",s.mapper().readValue(r.get("components").toString(),List.class));}catch(Exception e){throw MarginService.bad("Profilo non valido");}}return Map.of("items",rows);}
 @PostMapping("/profiles") @Transactional public Map<String,Object> profile(@RequestBody Profile p,Authentication a){s.require(a,"MARGINS_WRITE");if(p.name()==null||p.name().isBlank()||p.name().length()>200||p.components()==null||p.components().isEmpty()||p.components().size()>30||p.components().stream().anyMatch(c->c==null||c.isBlank()||c.length()>100)||new HashSet<>(p.components()).size()!=p.components().size())throw MarginService.bad("Nome e componenti univoche obbligatori");return Map.of("id",s.database().queryForObject("INSERT INTO penny_margin_profiles(name,components) VALUES (?,?::jsonb) RETURNING id",Long.class,p.name().trim(),s.encode(p.components())));}
 @GetMapping("/rules") public Map<String,Object> rules(Authentication a){s.require(a,"MARGINS_READ");return Map.of("items",s.database().queryForList("SELECT r.*,p.name AS \"profileName\" FROM penny_margin_rules r JOIN penny_margin_profiles p ON p.id=r.profile_id ORDER BY r.id DESC"));}
 @PostMapping("/rules") @Transactional public Map<String,Object> rule(@RequestBody Rule r,Authentication a){s.require(a,"MARGINS_WRITE");if(r.profileId()==null||r.name()==null||r.name().isBlank()||r.name().length()>200||r.component()==null||r.calculation()==null||!Set.of("PERCENT","FIXED").contains(r.calculation())||r.value()==null||r.value().signum()<0||r.value().precision()>20||r.value().scale()>6||r.sign()==null||!Set.of(-1,1).contains(r.sign())||r.validFrom()==null||r.validTo()!=null&&r.validTo().isBefore(r.validFrom())||r.status()==null||!Set.of("ACTIVE","DRAFT","EXPIRED").contains(r.status()))throw MarginService.bad("Regola non valida");
 var profile=s.row("penny_margin_profiles",r.profileId());try{if(!s.mapper().readValue(profile.get("components").toString(),List.class).contains(r.component()))throw MarginService.bad("Componente assente dal profilo");}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw MarginService.bad("Profilo non valido");}
 var conditions=r.conditions()==null?Map.<String,Object>of():r.conditions();if(!Set.of("operationType","licenseType","productTypeId","categoryId").containsAll(conditions.keySet())||conditions.values().stream().anyMatch(v->v==null||v instanceof Map<?,?>||v instanceof List<?> l&&(l.isEmpty()||l.stream().anyMatch(Objects::isNull))))throw MarginService.bad("Condizioni non valide");
 if(r.previousId()!=null){var previous=s.row("penny_margin_rules",r.previousId());if(!previous.get("profile_id").equals(r.profileId())||!previous.get("component").equals(r.component()))throw MarginService.bad("Versione precedente non coerente");}
 return Map.of("id",s.database().queryForObject("INSERT INTO penny_margin_rules(profile_id,previous_id,name,component,calculation,value,sign,conditions,valid_from,valid_to,priority,status,reference,created_by) VALUES (?,?,?,?,?,?,?,?::jsonb,?,?,?,?,?,?) RETURNING id",Long.class,r.profileId(),r.previousId(),r.name().trim(),r.component(),r.calculation(),r.value(),r.sign(),s.encode(conditions),r.validFrom(),r.validTo(),r.priority()==null?0:r.priority(),r.status(),r.reference(),a.getName()));}
 @PostMapping("/rules/{id}/close") @Transactional public Map<String,Object> close(@PathVariable long id,@RequestBody RuleChange c,Authentication a){s.require(a,"MARGINS_WRITE");var old=s.row("penny_margin_rules",id);if(c.validTo()==null||c.validTo().isBefore(((java.sql.Date)old.get("valid_from")).toLocalDate()))throw MarginService.bad("Data finale non valida");audit(id,"CLOSE",Map.of("before",old,"request",c),c.reason(),a);s.database().update("UPDATE penny_margin_rules SET valid_to=? WHERE id=?",c.validTo(),id);return Map.of("updated",true);}
 @PostMapping("/rules/{id}/cancel") @Transactional public Map<String,Object> cancelRule(@PathVariable long id,@RequestBody RuleChange c,Authentication a){s.require(a,"MARGINS_WRITE");var old=s.row("penny_margin_rules",id);audit(id,"CANCEL",Map.of("before",old,"request",c),c.reason(),a);if(c.effectiveOn()!=null){LocalDate end=c.effectiveOn().minusDays(1);if(end.isBefore(((java.sql.Date)old.get("valid_from")).toLocalDate()))s.database().update("UPDATE penny_margin_rules SET status='CANCELLED' WHERE id=?",id);else s.database().update("UPDATE penny_margin_rules SET valid_to=least(coalesce(valid_to,?),?) WHERE id=?",end,end,id);}else s.database().update("UPDATE penny_margin_rules SET status='CANCELLED' WHERE id=?",id);return Map.of("updated",true);}
 void audit(long id,String action,Map<String,Object> old,String reason,Authentication a){s.database().update("INSERT INTO penny_margin_rule_audit(rule_id,action,before_data,reason,actor) VALUES (?,?,?::jsonb,?,?)",id,action,s.encode(old),MarginService.reason(reason),a.getName());}
 @GetMapping("/rules/{id}/history") public Map<String,Object> history(@PathVariable long id,Authentication a){s.require(a,"MARGINS_READ");return Map.of("items",s.database().queryForList("SELECT * FROM penny_margin_rule_audit WHERE rule_id=? ORDER BY id",id));}
 @GetMapping public Map<String,Object> report(@RequestParam(required=false) Long saleId,Authentication a){s.require(a,"MARGINS_READ");var items=s.report(saleId);BigDecimal theoretical=BigDecimal.ZERO,recognized=BigDecimal.ZERO;for(var r:items)if(Boolean.TRUE.equals(r.get("current"))){theoretical=theoretical.add(new BigDecimal(r.get("calculated").toString()));recognized=recognized.add(new BigDecimal(r.get("recognized").toString()));}return Map.of("items",items,"theoretical",theoretical.toPlainString(),"recognized",recognized.toPlainString());}
 @PostMapping("/{id}/events") public Map<String,Object> change(@PathVariable long id,@RequestBody Change c,Authentication a){s.change(id,c.kind(),c.amount(),c.reason(),a);return Map.of("updated",true);}
 @GetMapping("/{id}/events") public Map<String,Object> events(@PathVariable long id,Authentication a){s.require(a,"MARGINS_READ");return Map.of("items",s.database().queryForList("SELECT * FROM penny_margin_events WHERE snapshot_id=? ORDER BY id",id));}
 @PostMapping("/sales/{id}/reevaluate") public Map<String,Object> reevaluate(@PathVariable long id,@RequestBody Change c,Authentication a){s.reevaluate(id,c.reason(),a);return Map.of("updated",true);}
}
